/**
 * public function grab_focus_without_selecting(): bool
 * Take the keyboard focus without selecting the text, or false when the widget cannot.
 *
 * Focus belongs to a toplevel: GTK hands it to the widget's root, and a widget that is not in a
 * window yet has none - `gtk_root_set_focus(NULL)` CRITICALs and the call answers false anyway.
 * `grab_focus()` itself checks first and simply returns false, so this matches it.
 */
ZEND_METHOD(Gtk4_GtkEntry, grab_focus_without_selecting) {
  ZEND_PARSE_PARAMETERS_NONE();
  GtkEntry *self = PHPGTK_SELF(GtkEntry, GTK_TYPE_ENTRY);
  if (gtk_widget_get_root(GTK_WIDGET(self)) == nullptr) RETURN_FALSE;
  RETURN_BOOL(gtk_entry_grab_focus_without_selecting(self));
}

// vfunc thunks and installers: file-local, installed by class_init of a PHP subtype
namespace {

// vfunc thunk: GTK_ENTRY_CLASS->activate -> $this->vfunc_activate() on a PHP subclass
void vfunc_thunk_activate(GtkEntry *self) {
  zval zself;
  zend_function *fn =
      EG(exception) == nullptr ? subtype_vfunc(G_OBJECT(self), "vfunc_activate", &zself) : nullptr;
  if (fn == nullptr) {  // no handle (mid-construction, after shutdown) or exception pending
    auto *native = GTK_ENTRY_CLASS(subtype_native_class(G_OBJECT(self)));
    if (native->activate != nullptr) native->activate(self);
    return;
  }
  zval ret;
  ZVAL_UNDEF(&ret);
  zend_call_known_instance_method(fn, Z_OBJ(zself), &ret, 0, nullptr);
  zval_ptr_dtor(&ret);
  zval_ptr_dtor(&zself);
  report_pending_exception("GtkEntry::vfunc_activate");
}

// vfunc installer: GTK_ENTRY_CLASS->activate (called from class_init / iface_init of a PHP subtype)
void vfunc_install_activate(gpointer klass) {
  GTK_ENTRY_CLASS(klass)->activate = vfunc_thunk_activate;
}

}  // namespace

/**
 * Gtk4\GtkEntry::vfunc_activate(): void
 *
 * Native `activate` (EntryClass.activate): the GTK implementation below any PHP subclass, for
 * `parent::vfunc_activate()` from an override. Class handler for the `GtkEntry::activate` signal.
 * The default implementation activates the gtk.activate-default action.
 */
ZEND_METHOD(Gtk4_GtkEntry, vfunc_activate) {
  ZEND_PARSE_PARAMETERS_NONE();
  GtkEntry *self = PHPGTK_SELF(GtkEntry, GTK_TYPE_ENTRY);
  if (!is_php_type(G_OBJECT_TYPE(self))) {
    zend_throw_exception_ex(spl_ce_LogicException, 0,
                            "GtkEntry::vfunc_activate(): for parent:: chaining from a PHP subclass "
                            "only; call the public method instead");
    RETURN_THROWS();
  }
  auto *klass = GTK_ENTRY_CLASS(subtype_native_class(G_OBJECT(self)));
  if (klass->activate == nullptr) {
    return;
  }
  klass->activate(self);
}

// MINIT: the vfunc thunks of GtkEntry (core/subtype.h).
void register_vfuncs_GtkEntry() {
  register_vfunc(GTK_TYPE_ENTRY, "activate", vfunc_install_activate);
}
